const $=id=>document.getElementById(id);
const labels={submitted:'Submitted',acknowledged:'Acknowledged',in_progress:'In progress',completed:'Completed',cancelled:'Cancelled'};
const next={submitted:['acknowledged','Acknowledge'],acknowledged:['in_progress','Start request'],in_progress:['completed','Mark completed']};
let signedIn=false,generation=0,busy=false,timer,rows=[];
function lock(){signedIn=false;generation++;clearTimeout(timer);rows=[];$('requests').replaceChildren();$('board').hidden=true;$('loginForm').hidden=false;$('crewCode').value='';}
async function api(input){const response=await fetch('/api/crew-dashboard',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(input)});const data=await response.json();if(!response.ok){if(response.status===401)lock();throw Error(data.error||'Dashboard unavailable.');}return data;}
function render(){const seat=$('seatFilter').value.trim().toUpperCase(),status=$('statusFilter').value;const visible=rows.filter(r=>(!seat||r.seat.toUpperCase().includes(seat))&&(status==='all'||(status==='active'?!['completed','cancelled'].includes(r.status):r.status===status)));$('requests').replaceChildren();$('summary').textContent=visible.length+' matching demo request'+(visible.length===1?'':'s');$('empty').hidden=visible.length!==0;for(const r of visible){const row=document.createElement('tr');const cell=text=>{const td=document.createElement('td');td.textContent=text;row.append(td);return td;};cell(r.seat);const description=cell(r.details);const category=document.createElement('small');category.textContent=r.category;description.append(category);cell(new Date(r.createdAt).toLocaleTimeString());const state=cell('');const badge=document.createElement('span');badge.className='badge';badge.textContent=labels[r.status]||r.status;state.append(badge);if(r.updatedAt){const time=document.createElement('small');time.textContent='Updated '+new Date(r.updatedAt).toLocaleTimeString();state.append(time);}const controls=cell('');if(next[r.status]){const [status,title]=next[r.status],button=document.createElement('button');button.textContent=title;button.disabled=busy;button.onclick=()=>update(r,status);controls.append(button);}$('requests').append(row);}}
async function load(){if(!signedIn||busy)return;busy=true;const mine=generation;clearTimeout(timer);try{const data=await api({action:'list'});if(mine!==generation)return;rows=data.requests;$('status').textContent='Last refreshed '+new Date().toLocaleTimeString();}catch(e){if(mine===generation||!signedIn)$('status').textContent=e.message;}finally{busy=false;if(signedIn&&mine===generation){render();timer=setTimeout(load,10000);}}}
async function update(row,status){if(busy)return;busy=true;render();try{await api({action:'update',sessionId:row.sessionId,id:row.id,expectedStatus:row.status,status});$('status').textContent='Demo status updated.';}catch(e){$('status').textContent=e.message;}finally{busy=false;if(signedIn)await load();}}
$('loginForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{await api({action:'login',code:$('crewCode').value});signedIn=true;generation++;$('loginForm').hidden=true;$('board').hidden=false;await load();}catch(e){$('status').textContent=e.message;}finally{$('crewCode').value='';button.disabled=false;}};
$('refresh').onclick=load;$('seatFilter').oninput=render;$('statusFilter').onchange=render;
$('logout').onclick=async()=>{try{await api({action:'logout'});}finally{lock();$('status').textContent='Crew dashboard signed out.';}};
signedIn=true;$('board').hidden=false;$('loginForm').hidden=true;void load();
